const SEED_CITIES: Record<string, string[]> = Object.fromEntries(
  RAW.trim()
    .split('\n')
    .map((line) => {
      const [code, list] = line.split(':');
      return [code.trim(), list.split(',').map((c) => c.trim())];
    }),
);

export const getSeedCities = (countryCode: string): string[] => SEED_CITIES[countryCode] ?? [];
